<?php
declare(strict_types=1);require_once __DIR__.'/includes/layout.php';require_once __DIR__.'/includes/service_engine.php';login_required();$pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=post('action');$id=post('id');if($action==='delete'&&$id!==''){try{$pdo->prepare("DELETE FROM `laundry` WHERE `laundry_id`=?")->execute([$id]);flash('success','Laundry deleted.');}catch(Throwable $e){flash('error','This record is in use and cannot be deleted.');}}redirect('laundry.php');}
$rows=$pdo->query('SELECT * FROM `laundry` ORDER BY `laundry_id` DESC')->fetchAll();page_header('Laundry','laundry');?>
<div class="page-head"><div><h1>Laundry</h1><p class="muted">Manage Laundry records and related guest services.</p></div><a class="btn primary" href="laundry_form.php">Add Laundry</a></div>
<section class="card table-wrap"><table><thead><tr><th>ID</th><th>Open</th><th>Close</th><th>Details</th><th>Actions</th></tr></thead><tbody>
<?php foreach($rows as $r):?><tr><td><?=e($r['laundry_id'])?></td><td><?=e($r['laundry_open_time'])?></td><td><?=e($r['laundry_close_time'])?></td><td><?=e($r['laundry_details'])?></td><td class="actions"><a href="laundry_form.php?id=<?=urlencode((string)$r['laundry_id'])?>">Edit</a><a href="laundry_service.php?id=<?=urlencode((string)$r['laundry_id'])?>">Add Service</a><form method="post" onsubmit="return confirm('Are you sure?')"><?=csrf_field()?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=e($r['laundry_id'])?>"><button class="danger-link">Delete</button></form></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="5" class="empty">No records.</td></tr><?php endif;?></tbody></table></section><?php page_footer();?>
